sed -i 's/val allInstalledApps = remember { getInstalledApps(context) }/val allInstalledApps = remember { getInstalledApps(context) }\n    val savedClassifications by homeViewModel?.appClassifications?.collectAsState() ?: mutableStateOf(emptyList())\n    \n    val appList = remember(allInstalledApps, savedClassifications) {\n        allInstalledApps.filter { appInfo ->\n            val clazz = savedClassifications.find { it.packageName == appInfo.packageName }?.classification\n                ?: getDefaultClassification(appInfo.packageName)\n            clazz == "DISTRACTING"\n        }\n    }/g' app/src/main/java/com/example/features/settings/AddLimitWizard.kt
sed -i 's/items(allInstalledApps) { appInfo ->/items(appList) { appInfo ->/g' app/src/main/java/com/example/features/settings/AddLimitWizard.kt
sed -i 's/fun AddLimitWizard(/fun AddLimitWizard(\n    homeViewModel: HomeViewModel?,/g' app/src/main/java/com/example/features/settings/AddLimitWizard.kt
